#include <cassert>
#include <cmath>
#include <filesystem>

#include "agent/eval/governance.hpp"

int main(){using namespace agent_framework;using namespace agent_framework::eval;DatasetRegistry registry;DatasetManifest manifest;manifest.metadata.identity.tenant_id="tenant";manifest.metadata.identity.task_id="eval";manifest.metadata.identity.run_id="run";manifest.dataset_id="phase4-core";manifest.version="2026.08.11";manifest.license="Apache-2.0";manifest.created_at="2026-08-11T00:00:00Z";
    const std::vector<DatasetLayer> layers{DatasetLayer::Unit,DatasetLayer::Repository,DatasetLayer::Domain,DatasetLayer::Adversarial,DatasetLayer::Recovery,DatasetLayer::Live};int index=0;for(const auto layer:layers){DatasetCase item;item.metadata=manifest.metadata;item.case_id="case-"+std::to_string(index++);item.input="input";item.criterion_ids={"correct"};item.tags={"layer:"+dataset_layer_name(layer)};item.license=manifest.license;item.dataset_version=manifest.version;assert(registry.register_case(item));manifest.layers.push_back({layer,{item.case_id},{encode(item).at("canonical_digest")}});}
    auto valid=validate_manifest(manifest,registry);assert(valid.valid&&valid.issues.empty()&&!valid.digest.empty());auto missing=manifest;missing.layers.pop_back();assert(!validate_manifest(missing,registry).valid);auto bad=manifest;bad.layers.front().case_digests.front()="sha256:tamper";assert(!validate_manifest(bad,registry).valid);
    std::vector<HumanLabel> labels;auto add=[&](std::string id,std::string reviewer,std::string value){HumanLabel label;label.metadata=manifest.metadata;label.label_id=id+reviewer;label.dataset_id=manifest.dataset_id;label.dataset_version=manifest.version;label.case_id=id;label.criterion_id="correct";label.reviewer_id=reviewer;label.reviewer_role="domain-reviewer";label.categorical_label=value;label.score=value=="pass"?1:0;label.evidence_ids={"evidence:"+id};label.created_at="now";labels.push_back(std::move(label));};add("a","r1","pass");add("a","r2","pass");add("b","r1","fail");add("b","r2","pass");add("c","r1","fail");add("c","r2","fail");std::string error;auto baseline=calculate_inter_rater_baseline(labels,&error);assert(baseline&&baseline->paired_items==3&&std::abs(baseline->raw_agreement-2.0/3.0)<1e-9&&baseline->disputed_item_ids.size()==1&&!baseline->digest.empty());labels.push_back(labels.front());assert(!calculate_inter_rater_baseline(labels,&error));
    CaseHistory stable{"stable",{true,true,true},{{"score",{1,1,1}}}};assert(!evaluate_flakiness(stable,{}).quarantined);CaseHistory flaky{"flaky",{true,false,true,true,true},{{"score",{1,0.7,1,0.8,1}}}};auto quarantine=evaluate_flakiness(flaky,{});assert(quarantine.quarantined&&!quarantine.digest.empty());CaseHistory failing{"failing",{false,false,true},{{}}};assert(!evaluate_flakiness(failing,{}).quarantined);
    CampaignSpec spec;spec.metadata=manifest.metadata;spec.campaign_id="nightly-1";spec.dataset_id=manifest.dataset_id;spec.dataset_version=manifest.version;spec.dataset_manifest_digest=encode(manifest).at("canonical_digest");spec.baseline_revision_digest="sha256:baseline";spec.candidate_revision_digest="sha256:candidate";spec.model_digest="sha256:model";spec.prompt_digest="sha256:prompt";spec.profile_digest="sha256:profile";spec.suite_digest="sha256:suite";spec.scheduled_at="2026-08-11T01:00:00Z";assert(validate_campaign_spec(spec,manifest,&error));auto tampered_spec=spec;tampered_spec.dataset_version="other";assert(!validate_campaign_spec(tampered_spec,manifest,&error));
    const auto path=(std::filesystem::temp_directory_path()/"phase4-eval-governance.sqlite").string();std::filesystem::remove(path);{
      SQLiteCampaignStore store(path);assert(store.put_manifest(manifest,&error));assert(store.put_spec(spec,&error));assert(!store.put_spec(spec,&error));assert(store.put_label(labels.front(),&error));assert(store.put_quarantine(spec.campaign_id,quarantine,&error));assert(store.acquire_lease({spec.campaign_id,"worker-a",200},100,&error));assert(!store.acquire_lease({spec.campaign_id,"worker-b",300},100,&error));assert(store.release_lease(spec.campaign_id,"worker-a"));assert(store.acquire_lease({spec.campaign_id,"worker-b",300},100,&error));
      CampaignReport report;report.metadata=manifest.metadata;report.campaign_id=spec.campaign_id;report.dataset_manifest_digest=spec.dataset_manifest_digest;report.spec_digest=campaign_spec_digest(spec);report.passed=true;report.metrics={{"quality",.91},{"latency",12}};report.quarantined_case_ids={quarantine.case_id};report.completed_at="2026-08-11T02:00:00Z";report.signature.algorithm="test-v1";report.signature.key_id="key-1";report.signature.signed_digest=campaign_report_signing_digest(report);report.signature.signature=report.signature.signed_digest+":signed";auto verifier=[](const CampaignSignature&s){return s.signature==s.signed_digest+":signed";};assert(validate_campaign_report(report,verifier,&error));auto tampered=report;tampered.metrics["quality"]=.1;assert(!validate_campaign_report(tampered,verifier,&error));assert(store.put_report(report,&error));assert(!store.put_report(report,&error));
    }
    {SQLiteCampaignStore reopened(path);auto loaded=reopened.load_spec(spec.campaign_id);auto report=reopened.load_report(spec.campaign_id);assert(loaded&&report&&report->metrics.at("quality")==.91);assert(reopened.report_history(spec.dataset_id,spec.dataset_version).size()==1);CampaignReport newer=*report;newer.metrics["quality"]=.95;auto trends=compare_campaign_reports(*report,newer);assert(trends.size()==2);auto quality=std::find_if(trends.begin(),trends.end(),[](const auto&v){return v.metric=="quality";});assert(quality!=trends.end()&&std::abs(quality->delta-.04)<1e-9);assert(reopened.acquire_lease({spec.campaign_id,"worker-c",400},301,&error));}
    std::filesystem::remove(path);return 0;}
